using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Text;
using BepInEx;
using BepInEx.Configuration;
using HarmonyLib;
using ServerSync;
using UnityEngine;

namespace DornsLevelbound
{
 [BepInPlugin(Guid, Name, Version)]
 [BepInDependency("WackyMole.EpicMMOSystem", BepInDependency.DependencyFlags.HardDependency)]
 public class Plugin : BaseUnityPlugin
 {
  public const string Guid="dorn.levelbound",Name="Levelbound",Version="0.4.0";
  internal static Plugin Instance;
  static readonly ConfigSync Sync=new ConfigSync(Guid){DisplayName=Name,CurrentVersion=Version,MinimumRequiredVersion=Version,ModRequired=true};
  static readonly CustomSyncedValue<Dictionary<string,string>> YamlData=new CustomSyncedValue<Dictionary<string,string>>(Sync,"Levelbound YAML");
  static readonly Heightmap.Biome[] Progression={Heightmap.Biome.Meadows,Heightmap.Biome.BlackForest,Heightmap.Biome.Swamp,Heightmap.Biome.Mountain,Heightmap.Biome.Plains,Heightmap.Biome.Mistlands,Heightmap.Biome.AshLands,Heightmap.Biome.DeepNorth};
  readonly Dictionary<Heightmap.Biome,BiomeRule> cfgBiomes=new Dictionary<Heightmap.Biome,BiomeRule>();
  readonly Dictionary<string,Heightmap.Biome> itemBiomes=new Dictionary<string,Heightmap.Biome>(StringComparer.OrdinalIgnoreCase);
  ConfigEntry<bool> locked,admin,generate,perBiome,diagnostic; BiomeRule global;
  FileSystemWatcher watcher; DateTime lastLoad=DateTime.MinValue; MethodInfo epicLevel; int cachedLevel; float nextLevel,nextBiomeMessage,nextItemMessage;
  string Folder{get{return Path.Combine(Paths.ConfigPath,"Levelbound");}} string Biomes{get{return Path.Combine(Folder,"biomas.yml");}} string Helper{get{return Path.Combine(Folder,"todos-itens-equipaveis.yml");}}
  void Awake(){Instance=this;Directory.CreateDirectory(Folder);BindAll();CreateFiles();YamlData.ValueChanged+=DebouncedLoad;if(Sync.IsSourceOfTruth)YamlData.AssignLocalValue(ReadYaml());Watch();DebouncedLoad();new Harmony(Guid).PatchAll();Logger.LogInfo("Levelbound "+Version+" carregado.");}
  void OnDestroy(){if(watcher!=null){watcher.EnableRaisingEvents=false;watcher.Dispose();}}
  ConfigEntry<T> Bind<T>(string s,string k,T d,string text){var e=Config.Bind(s,k,d,text);Sync.AddConfigEntry(e);return e;}
  BiomeRule AddRule(string section,int level){return new BiomeRule{Level=Bind(section,"NivelMinimo",level,"Nível mínimo do EpicMMO. Use 0 para desativar."),Craft=Bind(section,"BloquearCriacao",true,"Bloqueia criar e melhorar itens."),Equip=Bind(section,"BloquearEquipar",true,"Bloqueia equipar itens."),Consume=Bind(section,"BloquearConsumir",true,"Bloqueia consumir itens.")};}
  void BindAll(){locked=Bind("Geral","TravarConfiguracaoNoServidor",true,"Impede que clientes sobrescrevam configurações do servidor.");admin=Bind("Geral","IgnorarRestricoesParaAdmin",true,"Administradores e host ignoram restrições.");perBiome=Bind("Geral","UsarRegrasPorBioma",true,"Ativo: cada bioma usa sua seção. Desativado: todos usam Regras Globais.");generate=Bind("Geral","GerarListaDeItensEquipaveis",false,"Gera uma única vez a lista auxiliar agrupada por mod. Ela nunca é aplicada.");diagnostic=Bind("Geral","ModoDiagnostico",false,"Registra regras carregadas no log.");global=AddRule("Regras Globais",1);AddBiome("Meadows",Heightmap.Biome.Meadows,1);AddBiome("BlackForest",Heightmap.Biome.BlackForest,10);AddBiome("Swamp",Heightmap.Biome.Swamp,20);AddBiome("Mountain",Heightmap.Biome.Mountain,30);AddBiome("Plains",Heightmap.Biome.Plains,40);AddBiome("Mistlands",Heightmap.Biome.Mistlands,50);AddBiome("AshLands",Heightmap.Biome.AshLands,60);AddBiome("DeepNorth",Heightmap.Biome.DeepNorth,70);Sync.AddLockingConfigEntry(locked);}
  void AddBiome(string name,Heightmap.Biome biome,int level){cfgBiomes[biome]=AddRule("Biomas - "+name,level);}
  void CreateFiles(){if(File.Exists(Biomes))return;var s=new StringBuilder("# Levelbound: este YAML SOMENTE associa PrefabName a um bioma.\n# Níveis e todos os bloqueios ficam no CFG e são herdados pelo item.\n# A ordem abaixo é a progressão do jogo; não altere os nomes das oito seções.\n# Referencia é uma área livre para consulta e NUNCA aplica regras.\n\nReferencia:\n  ExemploDeMod:\n    - PrefabName: SwordIron\n\n");foreach(var b in Progression)s.Append(BiomeName(b)).Append(":\n#  - PrefabName: NomeDoPrefab\n");File.WriteAllText(Biomes,s.ToString());}
  Dictionary<string,string> ReadYaml(){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(File.Exists(Biomes))d[Biomes]=File.ReadAllText(Biomes);return d;}
  void Watch(){try{watcher=new FileSystemWatcher(Folder,"biomas.yml");watcher.SynchronizingObject=ThreadingHelper.SynchronizingObject;watcher.Changed+=Changed;watcher.Created+=Changed;watcher.Deleted+=Changed;watcher.Renamed+=Changed;watcher.EnableRaisingEvents=true;}catch(Exception e){Logger.LogWarning("Não foi possível monitorar YAML: "+e.Message);}}
  void Changed(object o,FileSystemEventArgs e){if(!Sync.IsSourceOfTruth)return;try{YamlData.AssignLocalValue(ReadYaml());DebouncedLoad();}catch(Exception x){Logger.LogWarning("Falha ao ler YAML: "+x.Message);}}
  void DebouncedLoad(){if((DateTime.UtcNow-lastLoad).TotalMilliseconds<300)return;lastLoad=DateTime.UtcNow;LoadRules();}
  void LoadRules(){itemBiomes.Clear();string text;var data=YamlData.Value;if(data!=null&&data.TryGetValue(Biomes,out text))ParseBiomes(text);if(diagnostic.Value)Logger.LogInfo("Associações carregadas: "+itemBiomes.Count+" itens.");}
  static string V(string s){int colon=s.IndexOf(':');return colon<0?"":s.Substring(colon+1).Trim().Trim('"','\'');}
  static string BiomeName(Heightmap.Biome b){return b==Heightmap.Biome.BlackForest?"BlackForest":b==Heightmap.Biome.AshLands?"AshLands":b.ToString();}
  static bool TryBiome(string text,out Heightmap.Biome biome){foreach(var b in Progression)if(string.Equals(BiomeName(b),text,StringComparison.OrdinalIgnoreCase)){biome=b;return true;}biome=Heightmap.Biome.None;return false;}
  void ParseBiomes(string yaml){Heightmap.Biome current=Heightmap.Biome.None;foreach(string row in yaml.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){string line=row.Trim();if(line.Length==0||line.StartsWith("#"))continue;if(!line.StartsWith("-")&&line.EndsWith(":")){Heightmap.Biome b;current=TryBiome(line.Substring(0,line.Length-1).Trim(),out b)?b:Heightmap.Biome.None;continue;}if(current!=Heightmap.Biome.None&&(line.StartsWith("- PrefabName:")||line.StartsWith("PrefabName:"))){string prefab=V(line);if(!string.IsNullOrEmpty(prefab))itemBiomes[prefab]=current;}}}
  internal int Level(){if(Time.time<nextLevel)return cachedLevel;nextLevel=Time.time+1f;try{if(epicLevel==null){Type t=Type.GetType("API.EpicMMOSystem_API, EpicMMOSystem")??Type.GetType("API.EMMOS_API, EpicMMOSystem");if(t!=null)epicLevel=t.GetMethod("GetLevel",BindingFlags.Public|BindingFlags.Static);}object x=epicLevel==null?null:epicLevel.Invoke(null,null);cachedLevel=x is int?(int)x:0;}catch{cachedLevel=0;}return cachedLevel;}
  internal bool Bypass(){return admin.Value&&(ZNet.instance==null||ZNet.instance.LocalPlayerIsAdminOrHost());}
  BiomeRule Rule(Heightmap.Biome biome){BiomeRule rule;return perBiome.Value&&cfgBiomes.TryGetValue(biome,out rule)?rule:global;}
  bool ItemRule(ItemDrop.ItemData item,out BiomeRule rule,out Heightmap.Biome biome){rule=null;biome=Heightmap.Biome.None;if(item==null||item.m_dropPrefab==null||!itemBiomes.TryGetValue(item.m_dropPrefab.name,out biome))return false;rule=Rule(biome);return true;}
  internal void CheckBiome(Player p){if(p!=Player.m_localPlayer||Bypass())return;BiomeRule r=Rule(p.GetCurrentBiome());if(r.Level.Value<=0||Level()>=r.Level.Value||Time.time<nextBiomeMessage)return;nextBiomeMessage=Time.time+5;MessageHud.instance.ShowMessage(MessageHud.MessageType.Center,"<color=#ff6666>Área bloqueada</color>: requer nível "+r.Level.Value+" do EpicMMO. Seu nível: "+Level()+".");}
  internal bool Blocked(ItemDrop.ItemData item,ActionKind action,out int requirement){requirement=0;if(Bypass())return false;BiomeRule r;Heightmap.Biome b;if(!ItemRule(item,out r,out b)||r.Level.Value<=0||Level()>=r.Level.Value)return false;bool enabled=action==ActionKind.Craft?r.Craft.Value:action==ActionKind.Equip?r.Equip.Value:r.Consume.Value;if(!enabled)return false;requirement=r.Level.Value;return true;}
  internal void Tell(int n){if(Time.time<nextItemMessage)return;nextItemMessage=Time.time+2;MessageHud.instance.ShowMessage(MessageHud.MessageType.Center,"<color=#ff6666>Ação bloqueada</color>: requer nível "+n+" do EpicMMO. Seu nível: "+Level()+".");}
  internal string RequirementText(ItemDrop.ItemData item,ActionKind action){BiomeRule r;Heightmap.Biome b;if(!ItemRule(item,out r,out b)||r.Level.Value<=0)return "";int current=Level();bool applies=action==ActionKind.Craft?r.Craft.Value:action==ActionKind.Equip?r.Equip.Value:r.Consume.Value;if(!applies)return "";string color=current>=r.Level.Value?"#66ff66":"#ff6666";return "\n<color="+color+">["+BiomeName(b)+"] Requer nível EpicMMO "+r.Level.Value+" (seu nível: "+current+")</color>";}
  string Origin(GameObject g){try{foreach(Component c in g.GetComponents<Component>()){if(c==null)continue;string n=c.GetType().Assembly.GetName().Name;if(n!="assembly_valheim"&&n!="UnityEngine"&&n!="Assembly-CSharp")return n;}}catch{}return "Valheim";}
  internal void Generate(ObjectDB db){if(!generate.Value||File.Exists(Helper)||db==null)return;var valid=new HashSet<string>{"Consumable","OneHandedWeapon","TwoHandedWeapon","TwoHandedWeaponLeft","Bow","Shield","Helmet","Chest","Ammo","Legs","Torch","Shoulder","Utility","Tool","Hands","Trinket"};var groups=new SortedDictionary<string,List<string>>(StringComparer.OrdinalIgnoreCase);foreach(GameObject g in db.m_items){ItemDrop d=g.GetComponent<ItemDrop>();if(d==null||d.m_itemData==null||d.m_itemData.m_shared==null||!valid.Contains(d.m_itemData.m_shared.m_itemType.ToString()))continue;string mod=Origin(g);List<string> list;if(!groups.TryGetValue(mod,out list))groups[mod]=list=new List<string>();list.Add(g.name);}var s=new StringBuilder("# Referência Levelbound: agrupada por mod de origem. NÃO é lida nem sincronizada.\n# Copie apenas PrefabName para uma das oito seções de biomas.yml.\n\nReferencia:\n");foreach(var group in groups){s.Append("  ").Append(group.Key).Append(":\n");group.Value.Sort(StringComparer.OrdinalIgnoreCase);foreach(string prefab in group.Value)s.Append("    - PrefabName: ").Append(prefab).Append("\n");}File.WriteAllText(Helper,s.ToString());Logger.LogInfo("Lista auxiliar criada: "+Helper);}
  internal enum ActionKind{Craft,Equip,Consume}
  class BiomeRule{public ConfigEntry<int> Level;public ConfigEntry<bool> Craft,Equip,Consume;}
 }
 [HarmonyPatch(typeof(Player),"UpdateBiome")] class BiomePatch{static void Postfix(Player __instance){if(Plugin.Instance!=null)Plugin.Instance.CheckBiome(__instance);}}
 [HarmonyPatch(typeof(Game),"RequestRespawn")] class GenPatch{static void Postfix(){if(Plugin.Instance!=null)Plugin.Instance.Generate(ObjectDB.instance);}}
 [HarmonyPatch(typeof(ItemDrop.ItemData),"IsEquipable")] class CanEquipPatch{static void Postfix(ItemDrop.ItemData __instance,ref bool __result){int n;if(__result&&Plugin.Instance!=null&&Plugin.Instance.Blocked(__instance,Plugin.ActionKind.Equip,out n))__result=false;}}
 [HarmonyPatch(typeof(Humanoid),"EquipItem")] class EquipPatch{static bool Prefix(Humanoid __instance,ItemDrop.ItemData item){int n;if(!__instance.IsPlayer()||Plugin.Instance==null||!Plugin.Instance.Blocked(item,Plugin.ActionKind.Equip,out n))return true;Plugin.Instance.Tell(n);return false;}}
 [HarmonyPatch(typeof(Player),"CanConsumeItem")] class EatPatch{static void Postfix(ItemDrop.ItemData item,ref bool __result){int n;if(__result&&Plugin.Instance!=null&&Plugin.Instance.Blocked(item,Plugin.ActionKind.Consume,out n)){__result=false;Plugin.Instance.Tell(n);}}}
 [HarmonyPatch(typeof(InventoryGui),"DoCrafting")] class CraftPatch{static readonly FieldInfo Selected=typeof(InventoryGui).GetField("m_selectedRecipe",BindingFlags.Instance|BindingFlags.NonPublic);static bool Prefix(InventoryGui __instance){if(__instance==null||Plugin.Instance==null||Selected==null)return true;object pair=Selected.GetValue(__instance);if(pair==null)return true;PropertyInfo p=pair.GetType().GetProperty("Recipe");Recipe recipe=p==null?null:p.GetValue(pair,null) as Recipe;if(recipe==null||recipe.m_item==null)return true;ItemDrop d=recipe.m_item.GetComponent<ItemDrop>();int n;if(d==null||!Plugin.Instance.Blocked(d.m_itemData,Plugin.ActionKind.Craft,out n))return true;Plugin.Instance.Tell(n);return false;}}
 [HarmonyPatch(typeof(ItemDrop.ItemData),"GetTooltip",new Type[]{typeof(int)})] class TooltipPatch{static void Postfix(ItemDrop.ItemData __instance,ref string __result){if(Plugin.Instance!=null)__result+=Plugin.Instance.RequirementText(__instance,Plugin.ActionKind.Equip);}}
 [HarmonyPatch(typeof(InventoryGui),"UpdateRecipe")] class RecipeVisualPatch{static readonly FieldInfo Selected=typeof(InventoryGui).GetField("m_selectedRecipe",BindingFlags.Instance|BindingFlags.NonPublic);static void Postfix(InventoryGui __instance){if(__instance==null||Plugin.Instance==null||Selected==null)return;object pair=Selected.GetValue(__instance);if(pair==null)return;PropertyInfo p=pair.GetType().GetProperty("Recipe");Recipe recipe=p==null?null:p.GetValue(pair,null) as Recipe;if(recipe==null||recipe.m_item==null)return;ItemDrop d=recipe.m_item.GetComponent<ItemDrop>();if(d==null)return;__instance.m_recipeDecription.text+=Plugin.Instance.RequirementText(d.m_itemData,Plugin.ActionKind.Craft);int n;if(Plugin.Instance.Blocked(d.m_itemData,Plugin.ActionKind.Craft,out n))__instance.m_craftButton.interactable=false;}}
}
